const ctx = $('Merge Auction + Lead Context').first().json;
const agents = $input.all();

return agents.map(item => {
  const agent = item.json;
  const body = [
    `\u{1F3E0} Nuevo lead para ${ctx.property_title}`,
    `\u{1F4B0} ${ctx.property_price}`,
    `\u{1F464} Lead: ${ctx.lead_name || 'Sin nombre'}`,
    ``,
    `Responde *TOMO-${ctx.short_code}* para asignartelo.`,
    `(Expira en 5 min)`
  ].join('\n');

  return {
    json: {
      agent_id: agent.agent_id,
      agent_name: agent.name,
      number: agent.whatsapp_number,
      text: body,
      t_propiedad: String(ctx.property_title || 'Propiedad'),
      t_precio: String(ctx.property_price || 'Sin precio'),
      t_nombre: String(ctx.lead_name || 'Sin nombre'),
      t_codigo: `TOMO-${ctx.short_code}`,
      t_minutos: '5',
      auction_id: ctx.auction_id,
      short_code: ctx.short_code,
      conversation_id: ctx.conversation_id
    }
  };
});

// Pair each Send result (Meta response) with its agent by index; record only real successes.
const sent = $('Send via Evolution').all();
const built = $('Build Fan-out Messages').all();
const notified = [], failed = [];
sent.forEach((it, i) => {
  const aid = built[i] ? built[i].json.agent_id : null;
  const r = it.json || {};
  const ok = !r.error && r.messages && r.messages[0] && r.messages[0].id;
  if (aid) (ok ? notified : failed).push(aid);
});
const c = built[0] ? built[0].json : {};
return [{ json: {
  auction_id: c.auction_id, conversation_id: c.conversation_id, short_code: c.short_code,
  notified_agents: notified, notified_count: notified.length,
  failed_agents: failed, failed_count: failed.length
} }];
